std::string digest(const std::string&s){return eventio::sha256(std::vector<std::uint8_t>(s.begin(),s.end()));}
template<class F>std::unique_ptr<ceres::CostFunction>ad(F f,const std::vector<int>&sizes,int n){return event_autodiff_cost(std::move(f),sizes,n);}
struct Physical{const EventModel*math=nullptr;EventPhysicalConstraint c;template<class T>bool operator()(T const*const*p,T*r)const{std::array<T,32>g{};for(int i=0;i<5;++i)g[i]=p[0][i];std::vector<const T*>q={g.data()};for(std::size_t i=1;i<c.block_ids.size();++i)q.push_back(p[i]);try{if(c.type==13){const T*a=p[1];std::vector<T>angles={a[3],a[3]+T(3.14159265358979323846)};const double step=1.5707963267948966;for(int k=int(std::ceil(event_scalar(a[3])/step));k<=int(std::floor((event_scalar(a[3])+3.14159265358979323846)/step));++k)angles.push_back(T(k*step));T x=T(0),y=T(0);using std::cos;using std::sin;using std::abs;for(const auto&t:angles){T xx=abs(a[0]+a[2]*cos(t)),yy=abs(a[1]+a[2]*sin(t));if(event_scalar(xx)>event_scalar(x))x=xx;if(event_scalar(yy)>event_scalar(y))y=yy;}r[0]=EventModel::rink_membership(x,y,g.data());}else if(c.type==14)r[0]=T(1e-6)-p[1][2];else if(c.type==15)r[0]=c.direction?p[1][c.index]-p[0][4]:-p[1][c.index];else if(c.type==16){const T*a=p[1];using std::sqrt;if(c.index==0)r[0]=T(1e-12)-a[2];else if(c.index==1)r[0]=T(1e-12)-a[4];else if(c.index==2)r[0]=a[4]-a[1];else if(c.index==3)r[0]=a[1]+a[4]-p[0][4];else {const T per=T(2)*(T(1)-T(2)*p[0][1]+p[0][0]-T(2)*p[0][2])+T(4)*EventModel::quarter_arclength(T(1.5707963267948966),p[0]);r[0]=T(2)*sqrt(a[2]*a[2]+a[3]*a[3])-per;}}else if(c.type==17){T lo=p[1][0],hi=lo;for(int k=2;k<c.index;k+=2){if(event_scalar(p[1][k])<event_scalar(lo))lo=p[1][k];if(event_scalar(p[1][k])>event_scalar(hi))hi=p[1][k];}const T per=T(2)*(T(1)-T(2)*p[0][1]+p[0][0]-T(2)*p[0][2])+T(4)*EventModel::quarter_arclength(T(1.5707963267948966),p[0]);r[0]=hi-lo-per;}else r[0]=math->evaluate_physical(c,q.data());return finite_scalar(r[0]);}catch(...){return false;}}};
