 for(std::size_t bi=0;bi<core.model.blocks.size();++bi){const auto&b=core.model.blocks[bi];if(b.name.rfind("print_component/polyline/",0)==0){if(b.values.size()%2)throw std::runtime_error("shared print polyline coordinate shape");for(std::size_t k=1;k<b.values.size();k+=2)for(int direction:{0,1}){EventPhysicalConstraint c;c.id=b.name+"/height_"+std::to_string(k/2)+"/"+std::to_string(direction);c.type=15;c.index=int(k);c.direction=direction;c.block_ids={0,int(bi)};physical_.push_back(c);}EventPhysicalConstraint c;c.id=b.name+"/finite_course_span";c.type=17;c.index=int(b.values.size());c.block_ids={0,int(bi)};physical_.push_back(c);}if(b.name.rfind("print_component/ellipse/",0)==0){if(b.values.size()!=5)throw std::runtime_error("shared print ellipse coordinate shape");for(int k=0;k<5;++k){EventPhysicalConstraint c;c.id=b.name+"/ellipse_domain_"+std::to_string(k);c.type=16;c.index=k;c.block_ids={0,int(bi)};physical_.push_back(c);}}}
