std::unique_ptr<JointALBuilder>JointALBuilder::frozen(const StateSnapshot&s)const{JointPacket packet;packet.schema=core.packet.schema;packet.source_hash=core.packet.source_hash;packet.rows=core.packet.rows;packet.groups=core.packet.groups;packet.source_json={{"schema",core.packet.source_json.at("schema")}};for(const char*key:{"engineering_scope","shot_ids","engineering_pixel_dependency_groups","allowed_paths"})if(core.packet.source_json.contains(key))packet.source_json[key]=core.packet.source_json.at(key);auto q=std::make_unique<JointALBuilder>(core.model,std::move(packet),allow_initialization_surrogate_,phase_one_geometry_guidance_);if(visible_ice_source_support_)q->attach_visible_ice_source_support(visible_ice_source_support_);if(source_query_branch_registry_)q->attach_source_query_branch_registry(source_query_branch_registry_);q->source_uv_capture_v1_=source_uv_capture_v1_;q->source_uv_capture_sensor_station_v2_=source_uv_capture_sensor_station_v2_;q->source_uv_capture_strict_v3_=source_uv_capture_strict_v3_;q->source_uv_capture_cells_v4_=source_uv_capture_cells_v4_;q->identity_=identity_;q->capture_cell_policy_ref_v20=capture_cell_policy_ref_v20;q->capture_cell_state_digest_v20=capture_cell_state_digest_v20;q->restore_state(s);return q;}
double*JointALBuilder::pointer(std::size_t i){auto m=core.model.blocks.size(),n=core.packet.rows.size();if(i<m)return core.model.blocks[i].values.data();if(i==m+3*n)return &budget_;if(i>m+3*n)return zoom_enclosures_.at(i-m-3*n-1).data();if(i<m+n)return &core.station.at(i-m);if(i<m+2*n)return &core.row.at(i-m-n);return &core.alpha.at(i-m-2*n);}
std::vector<int>JointALBuilder::sizes(const std::vector<std::size_t>&ids)const{std::vector<int>s;for(auto i:ids)s.push_back(i<core.model.blocks.size()?int(core.model.blocks[i].values.size()):(i>budget_id()?2:1));return s;}
std::vector<double*>JointALBuilder::pointers(const Factor&f){std::vector<double*>p;for(auto i:f.ids)p.push_back(pointer(i));return p;}
JointExplicitRow JointALBuilder::row(std::size_t i,std::vector<std::size_t>*ids)const{JointExplicitRow q;q.model=&core.model;q.source=&core.packet.rows.at(i);q.layout=q.source->layout(core.model);q.uv_cache=gpu_uv_.get();q.cache_row=i;for(auto id:q.layout.block_ids){q.physical_slots.push_back(int(ids->size()));ids->push_back(id);}if(q.source->kind!=1){q.station_slot=int(ids->size());ids->push_back(station_id(i));}q.row_slot=int(ids->size());ids->push_back(row_id(i));if(q.source->query){q.alpha_slot=int(ids->size());ids->push_back(alpha_id(i));}return q;}
void JointALBuilder::enable_gpu_raw_uv(const std::string&ptx,int threads,const std::filesystem::path&log_file){gpu_uv_=make_joint_gpu_uv_cache(core,&budget_,ptx,threads,log_file);}
void JointALBuilder::enable_gpu_raw_uv(const std::string&ptx,int threads,const std::filesystem::path&log_file,const std::string&abi){if(abi=="legacy_raw_uv_v1")enable_gpu_raw_uv(ptx,threads,log_file);else if(abi==joint_gpu::ice_line_width_kernel_abi)gpu_uv_=make_joint_gpu_width_uv_cache(core,&budget_,ptx,threads,log_file);else throw std::runtime_error("unsupported explicit raw UV kernel ABI");}
void JointALBuilder::enable_gpu_raw_uv(const std::string&ptx,int threads,const std::filesystem::path&log_file,const std::string&abi,bool reuse){if(source_uv_capture_sensor_station_v2_)gpu_uv_=make_joint_source_uv_capture_gpu_cache_v2(core,&budget_,ptx,threads,log_file,abi);else if(source_uv_capture_v1_)gpu_uv_=make_joint_source_uv_capture_gpu_cache_v1(core,&budget_,ptx,threads,log_file,abi);else if(reuse)gpu_uv_=make_joint_gpu_batch_reuse_uv_cache(core,&budget_,ptx,threads,log_file,abi);else enable_gpu_raw_uv(ptx,threads,log_file,abi);}

JointALBuilder::Factor JointALBuilder::pixel(std::size_t i)const{Factor f;auto q=row(i,&f.ids);int bs=int(f.ids.size());f.ids.push_back(budget_id());f.cost=joint_uv_scalar_cost(JointExplicitPixel{q,bs},sizes(f.ids));return f;}
JointALBuilder::Factor JointALBuilder::physical(std::size_t i)const{Factor f;for(auto id:physical_[i].block_ids)f.ids.push_back(id);f.cost=ad(Physical{&domain_math_,physical_[i]},sizes(f.ids),1);return f;}
JointSourceUVCaptureRowV1 JointALBuilder::capture_row_v1(std::size_t i,std::vector<std::size_t>*ids)const{JointSourceUVCaptureRowV1 v;auto s=std::make_shared<JointObservation>(core.packet.rows.at(i));s->query.reset();s->row=core.row.at(i);v.feasible_sensor_station=source_uv_capture_sensor_station_v2_;if(v.feasible_sensor_station&&s->kind!=1)s->station=core.station.at(i);v.source=s;v.implicit.model=&core.model;v.implicit.layout=s->layout(core.model);v.implicit.observation=s.get();for(std::size_t k=0;k<v.implicit.layout.block_ids.size();++k){ids->push_back(v.implicit.layout.block_ids[k]);v.implicit.parameter_sizes[int(k)]=int(core.model.blocks.at(v.implicit.layout.block_ids[k]).values.size());}if(s->kind!=1){v.implicit.station_slot=int(ids->size());ids->push_back(station_id(i));v.implicit.parameter_sizes[v.implicit.station_slot]=1;}v.cache=gpu_uv_.get();v.cache_row=i;return v;}
JointALBuilder::Factor JointALBuilder::native_domain(std::size_t i)const{Factor f;const auto&d=native_domains_[i];if(source_uv_capture_v1_){auto q=capture_row_v1(d.row,&f.ids);f.cost=ad(JointSourceUVCaptureDomainV1{q,d.kind},sizes(f.ids),1);}else{auto q=row(d.row,&f.ids);f.cost=ad(JointExplicitDomain{q,d.kind},sizes(f.ids),1);}return f;}
JointALBuilder::Factor JointALBuilder::zoom_bound(std::size_t i)const{Factor f;const auto&z=zoom_bounds_.at(i);f.ids={zoom_id(z.rig),std::size_t(z.control)};f.cost=ad(JointZoomControlBound{z.offset,z.upper},sizes(f.ids),1);return f;}
JointALBuilder::Factor JointALBuilder::zoom_certificate(std::size_t i)const{Factor f;const auto&rig=core.model.rigs.at(i/2);f.ids={std::size_t(rig.optics_block),zoom_id(i/2)};f.cost=ad(JointZoomCertificate{rig.math.f_ref,rig.math.radius_max,int(i%2),rig.math.wide_log_f_boundary,rig.math.wide_coefficients},sizes(f.ids),1);return f;}
JointALBuilder::Factor JointALBuilder::equality(std::size_t i)const{Factor f;if(i>=equalities_.size()){const auto&h=hard_equalities_.at(i-equalities_.size());f.ids=h.ids;f.cost=ad(h.functor,sizes(f.ids),1);return f;}const auto&d=equalities_[i];auto q=row(d.row,&f.ids);f.cost=joint_uv_scalar_cost(JointExplicitEquality{q,d.kind},sizes(f.ids));return f;}
JointALBuilder::Factor JointALBuilder::statistic(const JointStatisticalGroup&g)const{Factor f;JointExplicitStatistic v;v.group=&g;std::vector<std::vector<std::size_t>>local;for(auto i:g.rows){local.emplace_back();v.rows.push_back(row(i,&local.back()));for(auto id:local.back())if(std::find(f.ids.begin(),f.ids.end(),id)==f.ids.end())f.ids.push_back(id);}for(std::size_t k=0;k<v.rows.size();++k){std::vector<int>map;for(auto id:local[k])map.push_back(int(std::find(f.ids.begin(),f.ids.end(),id)-f.ids.begin()));v.rows[k]=v.rows[k].remap(map);}f.cost=ad(std::move(v),sizes(f.ids),int(g.rank));return f;}

void JointALBuilder::enable_source_uv_capture_v1(){if(gpu_uv_)throw std::runtime_error("select sourceUV/trueRS objective before GPU cache construction");source_uv_capture_v1_=true;identity_.objective_id="rinkfit.sourceUV_trueRS_finite_capture.v1";identity_.statistics_id=digest(core.packet.source_hash+"sourceUV_trueRS_engineering_E_not_likelihood_v1");}
void JointALBuilder::enable_source_uv_capture_v2(){enable_source_uv_capture_v1();source_uv_capture_sensor_station_v2_=true;identity_.objective_id="rinkfit.sourceUV_trueRS_finite_capture.v2";}
void JointALBuilder::enable_source_uv_capture_v3(){enable_source_uv_capture_v2();source_uv_capture_strict_v3_=true;identity_.objective_id="rinkfit.sourceUV_trueRS_finite_capture.v3";}
void JointALBuilder::enable_source_uv_capture_v4(){enable_source_uv_capture_v3();source_uv_capture_cells_v4_=true;identity_.objective_id="rinkfit.sourceUV_trueRS_finite_capture.v4";}
void JointALBuilder::set_engineering_identity(const std::string& configuration_sha){
 identity_.objective_id=source_uv_capture_cells_v4_?"rinkfit.sourceUV_trueRS_finite_capture.v4":source_uv_capture_strict_v3_?"rinkfit.sourceUV_trueRS_finite_capture.v3":source_uv_capture_sensor_station_v2_?"rinkfit.sourceUV_trueRS_finite_capture.v2":source_uv_capture_v1_?"rinkfit.sourceUV_trueRS_finite_capture.v1":"engineering_recovery_native_pixel_v1";
 identity_.statistics_id=digest(core.packet.source_hash+"engineering_not_likelihood|"+configuration_sha);
 identity_.budget_id=digest("no_common_budget_in_engineering_recovery");
}
