 for(auto i:active_){p.SetParameterLowerBound(&core.row[i],0,0);p.SetParameterUpperBound(&core.row[i],0,1079);}
 for(auto i:profile_rows_){p.SetParameterLowerBound(&core.alpha[i],0,core.packet.rows[i].query->alpha.front());p.SetParameterUpperBound(&core.alpha[i],0,core.packet.rows[i].query->alpha.back());}
 if(capture){for(auto i:active_){p.SetParameterBlockConstant(&core.row[i]);if(core.packet.rows[i].query)p.SetParameterBlockConstant(&core.alpha[i]);if(core.fixed_nuisance_shots.count(core.packet.rows[i].shot_id)&&core.packet.rows[i].kind!=1)p.SetParameterBlockConstant(&core.station[i]);}for(auto i:station_rows_){auto intervals=core.packet.rows[i].station_intervals(core.model,core.packet.rows[i].path);bool found=false;for(auto x:intervals)if(core.station[i]>=x[0]&&core.station[i]<=x[1]){p.SetParameterLowerBound(&core.station[i],0,x[0]);p.SetParameterUpperBound(&core.station[i],0,x[1]);found=true;break;}if(!found)throw std::runtime_error("sourceUV capture station outside original finite interval");}(*ledger)["original_W_likelihood_consumed"]=false;(*ledger)["source_UV_residual_dimensions"]=2;(*ledger)["RS_row_implicitly_eliminated"]=true;(*ledger)["formal_local_Query_consumed"]=false;(*ledger)["formal_Queries_UV_windows_rows_retained"]=true;(*ledger)["local_Query_failure_is_capture_success"]=false;}
 p.SetParameterBlockConstant(&budget_);
 (*ledger)["physical_inequality_factors"]=inv.inequality_blocks.size();(*ledger)["RS_Query_equality_factors"]=inv.equality_blocks.size();
 if(visible_ice_source_support_)(*ledger)["source_visible_ice_constraints"]=visible_ice_source_support_report();(*ledger)["physical_constraint_penalty"]=penalty;(*ledger)["common_budget_consumed"]=false;
