void JointALBuilder::visit_hybrid_native_Lagrangian_constraints_v1(const std::vector<double>&lambda,const std::vector<double>&nu,const HybridNativeFactorVisitorV1&visit){if(lambda.size()!=schema_.inequality_ids.size()||nu.size()!=equality_count())throw std::runtime_error("hybrid native Lagrangian full constraint dimension mismatch");auto emit=[&](Factor f,double weight){if(weight==0)return;auto p=pointers(f);visit(std::move(f.cost),std::move(p),weight);};std::size_t k=0;for(auto i:active_)emit(pixel(i),lambda.at(k++));for(std::size_t i=0;i<physical_.size();++i)emit(physical(i),lambda.at(k++));for(std::size_t i=0;i<native_domains_.size();++i)emit(native_domain(i),lambda.at(k++));for(std::size_t i=0;i<zoom_bounds_.size();++i)emit(zoom_bound(i),lambda.at(k++));for(std::size_t i=0;i<2*zoom_enclosures_.size();++i)emit(zoom_certificate(i),lambda.at(k++));for(std::size_t i=0;i<visible_ice_source_inequality_count();++i)emit(visible_ice_source_factor(i),lambda.at(k++));for(std::size_t i=0;i<equality_count();++i)emit(equality(i),nu.at(i));}
GradientReport JointALBuilder::project_hybrid_raw_gradient_v1(const std::map<double*,std::vector<double>>&raw,Phase phase,const std::string&token){GradientReport out;out.state_token=token;out.scales_id=identity().scales_id;std::map<std::size_t,std::vector<double>>grad;auto take=[&](std::size_t id,std::size_t n){auto p=pointer(id);auto it=raw.find(p);grad[id]=it==raw.end()?std::vector<double>(n,0.):it->second;if(grad[id].size()!=n)throw std::runtime_error("hybrid exact ambient gradient dimension mismatch");};for(std::size_t i=0;i<core.model.blocks.size();++i)take(i,core.model.blocks[i].values.size());for(auto i:station_rows_)take(station_id(i),1);for(auto i:active_)take(row_id(i),1);for(auto i:profile_rows_)take(alpha_id(i),1);take(budget_id(),1);for(std::size_t i=0;i<zoom_enclosures_.size();++i)take(zoom_id(i),2);for(auto i:station_rows_)if(core.packet.rows[i].query||core.fixed_nuisance_shots.count(core.packet.rows[i].shot_id))grad[station_id(i)][0]=0.;for(auto i:active_)grad[row_id(i)][0]=0.;for(auto i:profile_rows_)grad[alpha_id(i)][0]=0.;
bool tangent_complete=true;for(std::size_t i=0;i<core.model.blocks.size();++i){const auto&b=core.model.blocks[i];bool handled=false;for(const auto&d:core.model.source_json.value("linear_control_manifolds",eventio::Json::array()))if(d.at("block").get<std::size_t>()==i){for(int col=0;col<d.at("tangent_size").get<int>();++col){double g=0;for(std::size_t a=0;a<b.values.size();++a){g+=d.at("basis")[a][col].get<double>()*b.scales[a]*grad[i][a];if(!b.constant&&(b.values[a]-b.lower[a]<1e-10||b.upper[a]-b.values[a]<1e-10))tangent_complete=false;}out.scaled_projected_components.push_back(b.constant?0:g);}handled=true;}if(handled)continue;for(std::size_t j=0;j<b.values.size();++j)out.scaled_projected_components.push_back(b.constant||std::find(b.fixed_indices.begin(),b.fixed_indices.end(),j)!=b.fixed_indices.end()?0:projected_box_gradient(b.values[j],grad[i][j],b.scales[j],b.lower[j],b.upper[j]));}
 for(auto i:station_rows_)out.scaled_projected_components.push_back(projected_box_gradient(core.station[i],grad[station_id(i)][0],1,0,1));for(auto i:active_)out.scaled_projected_components.push_back(projected_box_gradient(core.row[i],grad[row_id(i)][0],1079,0,1079));for(auto i:profile_rows_){const auto&curve=*core.packet.rows[i].query;out.scaled_projected_components.push_back(projected_box_gradient(core.alpha[i],grad[alpha_id(i)][0],1,curve.alpha.front(),curve.alpha.back()));}out.scaled_projected_components.push_back(phase==Phase::kPrecision?0:projected_box_gradient(budget_,grad[budget_id()][0],1,0,INFINITY));for(std::size_t i=0;i<zoom_enclosures_.size();++i)for(int j=0;j<2;++j)out.scaled_projected_components.push_back(projected_box_gradient(zoom_enclosures_[i][j],grad[zoom_id(i)][j],1,zoom_box_[i][0],zoom_box_[i][1]));out.complete_current_derivatives=tangent_complete;return out;}
